// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { ClipboardIcon, PinIcon, SearchIcon } from 'lucide-react'
import type { ReactNode } from 'react'

import { BrowserChrome, DemoStage, DockHeader, Label, type Build } from '@/app/demos/stage'

import { CAPTIONS, OLDER, SNIPPETS } from './script'

const ROW = 36

function Item({
  d,
  children,
  hidden = false,
  pin,
}: {
  d: string
  children: ReactNode
  hidden?: boolean
  pin?: string
}) {
  return (
    <div
      data-d={d}
      className="overflow-hidden px-3"
      style={{ height: hidden ? 0 : ROW, opacity: hidden ? 0 : 1 }}
    >
      <div
        data-d={`${d}-card`}
        className="flex h-[30px] items-center gap-2 rounded-lg border border-line bg-canvas/70 px-2.5 text-[10px] text-ink-soft"
      >
        <ClipboardIcon className="size-3 shrink-0 text-muted" />
        <span className="min-w-0 flex-1 truncate font-mono">{children}</span>
        {pin ? (
          <span data-d={pin} className="flex size-4 items-center justify-center text-muted">
            <PinIcon className="size-3" />
          </span>
        ) : null}
      </div>
    </div>
  )
}

const build: Build = ({ tl, q, qa, step, final, move, click, type, fly, wait, cursorOut }) => {
  const copy = (index: 1 | 2) => {
    move(`sel-${index}`, { ax: 0.05 })
    tl.to(q(`sel-${index}`), {
      backgroundColor: 'rgba(56,189,248,0.35)',
      duration: 0.4,
      ease: 'none',
    })
    tl.fromTo(
      q('keys'),
      { opacity: 0, y: 6, scale: 0.8 },
      { opacity: 1, y: 0, scale: 1, duration: 0.3, ease: 'back.out(3)' },
      '+=0.1',
    )
    tl.to(q('keys'), { opacity: 0, duration: 0.2 }, '+=0.35')
    fly(`ghost-${index}`, `sel-${index}`, `new-${index}`, { duration: 0.75, lift: 50 })
    tl.to(
      q(`new-${index}`),
      { height: ROW, opacity: 1, duration: 0.35, ease: 'power3.out' },
      '-=0.2',
    )
    tl.to(q(`ghost-${index}`), { opacity: 0, duration: 0.15 }, '<0.2')
    tl.to(q(`sel-${index}`), { backgroundColor: 'rgba(56,189,248,0)', duration: 0.3 }, '<')
  }

  step(0)
  copy(1)
  copy(2)

  step(1, '+=0.4')
  move('search')
  click('search')
  type('search-text', 'api', { speed: 0.12 })
  tl.to(
    qa('nomatch'),
    { height: 0, opacity: 0, duration: 0.4, stagger: 0.05, ease: 'power3.inOut' },
    '<0.2',
  )
  tl.to(q('mark'), { backgroundColor: 'rgba(251,191,36,0.4)', duration: 0.3 }, '<0.2')

  step(2, '+=0.5')
  move('pin-2')
  click('pin-2')
  tl.to(q('pin-2'), { color: '#a78bfa', rotate: -30, duration: 0.2 }, '<')
  tl.to(q('empty'), { height: 0, opacity: 0, duration: 0.25 }, '<')
  fly('ghost-2', 'new-2', 'pinned', { duration: 0.6, lift: 30 })
  tl.to(q('new-2'), { height: 0, opacity: 0, duration: 0.3 }, '<')
  tl.to(q('pinned'), { height: ROW, opacity: 1, duration: 0.3 }, '-=0.15')
  tl.to(q('ghost-2'), { opacity: 0, duration: 0.15 }, '<0.15')

  step(3, '+=0.5')
  tl.to(q('search-text'), { text: '', duration: 0.2 })
  tl.to(qa('nomatch'), { height: ROW, opacity: 1, duration: 0.35, stagger: 0.04 }, '<')
  tl.to(q('mark'), { backgroundColor: 'rgba(251,191,36,0)', duration: 0.2 }, '<')
  move('pinned-card', { at: '+=0.1' })
  click('pinned-card')
  tl.fromTo(q('toast'), { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: 0.3 }, '<')
  move('field', { ax: 0.2 })
  click('field')
  tl.to(q('toast'), { opacity: 0, duration: 0.2 }, '<')
  tl.set(q('field-text'), { text: SNIPPETS.key })
  tl.fromTo(q('field-text'), { opacity: 0 }, { opacity: 1, duration: 0.25 })
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="Clipboard Manager collecting copied snippets, searching them and pinning one"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://docs.acme.dev/quickstart"
        panelWidth={212}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="px-3 pt-3">
              <div
                data-d="search"
                className="flex h-7 items-center gap-1.5 rounded-lg border border-line bg-canvas/80 px-2 text-[10px]"
              >
                <SearchIcon className="size-3 text-muted" />
                <span data-d="search-text" className="demo-caret text-ink" />
              </div>
            </div>
            <Label className="px-3 pb-1.5 pt-3">Pinned</Label>
            <p
              data-d="empty"
              className="overflow-hidden px-3 text-[10px] text-muted"
              style={{ height: 20 }}
            >
              No pinned items
            </p>
            <Item d="pinned" hidden>
              <span className="text-ink">{SNIPPETS.key}</span>
            </Item>
            <Label className="px-3 pb-1.5 pt-2">History</Label>
            <Item d="new-2" hidden pin="pin-2">
              <span data-d="mark" className="rounded-sm">
                api
              </span>
              {SNIPPETS.key.slice(3)}
            </Item>
            <Item d="new-1 nomatch" hidden>
              {SNIPPETS.install}
            </Item>
            {OLDER.map((text) => (
              <Item key={text} d="nomatch">
                {text}
              </Item>
            ))}
            <span
              data-d="toast"
              className="absolute bottom-3 left-1/2 -translate-x-1/2 rounded-full bg-[var(--accent)] px-2.5 py-1 text-[10px] font-medium text-canvas opacity-0"
            >
              Copied
            </span>
          </div>
        }
      >
        <div className="h-full bg-[#fafafa] px-5 pt-4 text-[#111]">
          <p className="text-[8px] uppercase tracking-[0.2em] text-[#2563eb]">Quickstart</p>
          <h3 className="text-[15px] font-bold tracking-tight">Install the SDK</h3>
          <p className="mt-1.5 text-[9.5px] leading-relaxed text-[#555]">
            Add the package to your project, then create a key in the dashboard.
          </p>
          <div className="mt-2.5 rounded-md bg-[#0f172a] px-2.5 py-2 font-mono text-[10px] text-[#e2e8f0]">
            <span className="text-[#64748b]">$ </span>
            <span data-d="sel-1" className="rounded-sm">
              {SNIPPETS.install}
            </span>
          </div>
          <p className="mt-3 text-[9.5px] leading-relaxed text-[#555]">
            Requests go to{' '}
            <span data-d="sel-2" className="rounded-sm font-mono text-[#2563eb]">
              {SNIPPETS.key}
            </span>{' '}
            with your key in the header.
          </p>
          <p className="mt-4 text-[8.5px] font-medium uppercase tracking-[0.14em] text-[#666]">
            Endpoint
          </p>
          <div
            data-d="field"
            className="mt-1 flex h-7 items-center rounded-md border border-[#ddd] bg-white px-2 font-mono text-[10px]"
          >
            <span data-d="field-text" className="text-[#111]" />
          </div>
          <span
            data-d="keys"
            className="absolute right-4 top-24 rounded-md border border-[#ccc] bg-white px-2 py-1 font-mono text-[10px] text-[#333] opacity-0 shadow"
          >
            Ctrl + C
          </span>
        </div>
      </BrowserChrome>
      {(['1', '2'] as const).map((index) => (
        <span
          key={index}
          data-d={`ghost-${index}`}
          className="absolute left-0 top-0 z-30 rounded-lg border border-[#a78bfa]/60 bg-elevated px-2.5 py-1.5 font-mono text-[10px] text-ink opacity-0 shadow-xl"
        >
          {index === '1' ? SNIPPETS.install : SNIPPETS.key}
        </span>
      ))}
    </DemoStage>
  )
}
